class Solution:
    def missingMultiple(self, nums: List[int], k: int) -> int:
        count = [0] * 102
        for num in nums:
            if num % k == 0:
                count[num//k] += 1

        for i in range(1, len(count)):
            if count[i] == 0:
                return i * k 

        return k
